def divide(x, y):
    if y == 0:
        raise ValueError('Division par zero')
    return x / y

def factorial(n):
    if n <= 1:
        return 1
    return n * factorial(n - 1)

def reverse_string(s):
    return s[::-1]

def is_palindrome(s):
    return s == s[::-1]

class UserManager:
    def __init__(self):
        self.users = []

    def add_user(self, username, email):
        user = {'username': username, 'email': email}
        self.users.append(user)
        return user

    def get_user(self, username):
        for user in self.users:
            if user['username'] == username:
                return user
        return None

class DataProcessor:
    def __init__(self, data):
        self.data = data

    def clean_data(self):
        # Nettoyage des données
        cleaned = []
        for item in self.data:
            if item is not None:
                cleaned.append(item.strip())
        self.data = cleaned
        return self.data

    def filter_data(self, min_length):
        # Filtrage par longueur
        filtered = []
        for item in self.data:
            if len(item) >= min_length:
                filtered.append(item)
        return filtered

    def transform_data(self, func):
        # Transformation avec une fonction
        return [func(item) for item in self.data]

    def aggregate_data(self):
        # Agrégation
        return {
            'count': len(self.data),
            'unique': len(set(self.data)),
            'max_length': max(len(item) for item in self.data) if self.data else 0
        }

    def export_data(self, format='json'):
        # Export
        if format == 'json':
            import json
            return json.dumps(self.data)
        return str(self.data)
